def configure(backends, raise_errors=False):
    good_backends = []

    for backend in backends:
        clspath = backend['class']
        options = backend.get('options', {})

        if isinstance(clspath, str):
            modpath, clsname = split_clspath(clspath)
            try:
                __import__(modpath)
                module = sys.modules[modpath]
                cls = getattr(module, clsname)
            except Exception:
                logger.exception('Exception while importing %s', clspath)
                if raise_errors:
                    raise
                continue
        else:
            cls = clspath

        try:
            good_backends.append(cls(options))
        except Exception:
            logger.exception(
                'Exception thrown while instantiating %s, %s',
                clspath,
                options
            )
            if raise_errors:
                raise

    _change_metrics(good_backends)

def get_metrics(thing, extra=''):
    thing = thing or ''

    if not isinstance(thing, str):
        # If it's not a str, it's either a class or an instance. Handle
        # accordingly.
        if type(thing) == type:
            thing = '%s.%s' % (thing.__module__, thing.__name__)
        else:
            thing = '%s.%s' % (
                thing.__class__.__module__, thing.__class__.__name__
            )

    if extra:
        thing = '%s.%s' % (thing, extra)

    return MetricsInterface(thing)

def timer(self, stat, tags=None):
        if six.PY3:
            start_time = time.perf_counter()
        else:
            start_time = time.time()

        yield

        if six.PY3:
            end_time = time.perf_counter()
        else:
            end_time = time.time()

        delta = end_time - start_time
        self.timing(stat, value=delta * 1000.0, tags=tags)

def timer_decorator(self, stat, tags=None):
        def _inner(fun):
            @wraps(fun)
            def _timer_decorator(*args, **kwargs):
                with self.timer(stat, tags):
                    return fun(*args, **kwargs)
            return _timer_decorator
        return _inner

def generate_tag(key, value=None):
    # Verify the types
    if not isinstance(key, six.string_types):
        raise ValueError('key must be a string type, but got %r instead' % key)

    if not isinstance(value, six.string_types + (NONE_TYPE,)):
        raise ValueError('value must be None or a string type, but got %r instead' % value)

    # Sanitize the key
    key = BAD_TAG_CHAR_REGEXP.sub('_', key).strip()

    # Build the tag
    if value is None or not value.strip():
        tag = key
    else:
        value = BAD_TAG_CHAR_REGEXP.sub('_', value).strip()
        tag = '%s:%s' % (key, value)

    if tag and not tag[0].isalpha():
        tag = 'a' + tag

    # Lowercase and truncate
    tag = tag.lower()[:200]

    # Add _ if it's a reserved word
    if tag in ['device', 'host', 'source']:
        tag = tag + '_'

    return tag

def count_id(w0):

    def f(w1):
        count = [set(w0.root).intersection(w1.root),
                 set(w0.flexing).intersection(w1.flexing),
                 set(w0.root).intersection(w1.flexing) | set(w1.root).intersection(w0.flexing)]

        if any(count):
            return max((1,2,3), key=lambda i: len(count[i - 1]))
        else:
            return 0

    return f

