def cartesianToSpherical(x, y, z):
  rCylSq=x*x+y*y
  r=sqrt(rCylSq+z*z)
  if any(r==0.0):
    raise Exception("Error: one or more of the points is at distance zero.")
  phi = arctan2(y,x)
  phi = where(phi<0.0, phi+2*pi, phi)
  return r, phi, arctan2(z,sqrt(rCylSq))

def enum(typename, field_names):

    if isinstance(field_names, str):
        field_names = field_names.replace(',', ' ').split()
    d = dict((reversed(nv) for nv in enumerate(field_names)), __slots__ = ())
    return type(typename, (object,), d)()

def construct_covariance_matrix(cvec, parallax, radial_velocity, radial_velocity_error):

    if np.ndim(cvec)==1:
        cmat = np.zeros((1,6,6))
        nsources = 1
        cv = np.atleast_2d(cvec)
    else:
        nsources = cvec.shape[0]
        cmat = np.zeros((nsources,6,6))
        cv = cvec
    for k in range(nsources):
        cmat[k,0:5,0:5] = cv[k,0:5]**2

    iu = np.triu_indices(5,k=1)
    for k in range(10):
        i = iu[0][k]
        j = iu[1][k]
        cmat[:,i,j] = cv[:,i]*cv[:,j]*cv[:,k+5]
        cmat[:,j,i] = cmat[:,i,j]

    for k in range(nsources):
        cmat[k,0:5,5] = cmat[k,0:5,2]*np.atleast_1d(radial_velocity)[k]/auKmYearPerSec
    cmat[:,5,0:5] = cmat[:,0:5,5]
    cmat[:,5,5] = cmat[:,2,2]*(radial_velocity**2 + radial_velocity_error**2)/auKmYearPerSec**2 + \
            (parallax*radial_velocity_error/auKmYearPerSec)**2

    return np.squeeze(cmat)

def gMagnitudeError(G):
  z=calcZ(G)
  return 1.0e-3*sqrt(0.04895*z*z + 1.8633*z + 0.0001985) * _scienceMargin

def bpMagnitudeErrorEoM(G, vmini, nobs=70):
  return sqrt( (power(bpMagnitudeError(G, vmini)/_scienceMargin,2) +
      _eomCalibrationFloorBP*_eomCalibrationFloorBP)/nobs ) * _scienceMargin

def rpMagnitudeErrorEoM(G, vmini, nobs=70):
  return sqrt( (power(rpMagnitudeError(G, vmini)/_scienceMargin,2) +
      _eomCalibrationFloorRP*_eomCalibrationFloorRP)/nobs ) * _scienceMargin

def calcZBpRp(G):
  gatefloor=power(10.0,0.4*(11.0-15.0))
  if isscalar(G):
   result=amax((gatefloor,power(10.0,0.4*(G-15.0))))
  else :
    result=power(10.0,0.4*(G-15.0))
    indices=(result<gatefloor)
    result[indices]=gatefloor
  return result

def calcZAltStartGate(G):
  gatefloor=power(10.0,0.4*(13.3-15.0))
  if isscalar(G):
   result=amax((gatefloor,power(10.0,0.4*(G-15.0))))
  else :
    result=power(10.0,0.4*(G-15.0))
    indices=(result<gatefloor)
    result[indices]=gatefloor
  return result

def transformProperMotions(self, phi, theta, muphistar, mutheta):
        c, s = self._getJacobian(phi,theta)
        return c*muphistar+s*mutheta, c*mutheta-s*muphistar

def _getJacobian(self, phi, theta):

        p, q, r = normalTriad(phi, theta)

        # zRot = z-axis of new coordinate system expressed in terms of old system
        zRot = self.rotationMatrix[2,:]

        if (p.ndim == 2):
            zRotAll = tile(zRot, p.shape[1]).reshape(p.shape[1],3)
            pRot = cross(zRotAll, r.T)
            normPRot = norm(pRot,axis=1)
            for i in range(pRot.shape[0]):
                pRot[i] = pRot[i]/normPRot[i]
            c = zeros(pRot.shape[0])
            s = zeros(pRot.shape[0])
            for i in range(pRot.shape[0]):
                c[i] = dot(pRot[i], p.T[i])
                s[i] = dot(pRot[i], q.T[i])
            return c, s
        else:
            pRot = cross(zRot, r.T)
            pRot = pRot/norm(pRot)
            return dot(pRot,p), dot(pRot,q)

def errorScalingFactor(observable, beta):
  if isscalar(beta):
    index=int(floor(abs(sin(beta))*_numStepsSinBeta))
    if index == _numStepsSinBeta:
      return _astrometricErrorFactors[observable][_numStepsSinBeta-1]
    else:
      return _astrometricErrorFactors[observable][index]
  else:
    indices = array(floor(abs(sin(beta))*_numStepsSinBeta), dtype=int)
    indices[(indices==_numStepsSinBeta)] = _numStepsSinBeta-1
    return _astrometricErrorFactors[observable][indices]

