original_source_with_docstring:
def lazyload(reference: str, *args, **kw):
	"""Lazily load and cache an object reference upon dereferencing.

	Assign the result of calling this function with either an object reference passed in positionally:

		class MyClass:
			debug = lazyload('logging:debug')

	Or the attribute path to traverse (using `marrow.package.loader:traverse`) prefixed by a period.

		class AnotherClass:
			target = 'logging:info'
			log = lazyload('.target')

	Additional arguments are passed to the eventual call to `load()`.
	"""

	assert check_argument_types()

	def lazily_load_reference(self):
		ref = reference

		if ref.startswith('.'):
			ref = traverse(self, ref[1:])

		return load(ref, *args, **kw)

	return lazy(lazily_load_reference)

code:
def parse_str_to_expression(fiql_str):
    #pylint: disable=too-many-branches
    nesting_lvl = 0
    last_element = None
    expression = Expression()
    for (preamble, selector, comparison, argument) in iter_parse(fiql_str):
        if preamble:
            for char in preamble:
                if char == '(':
                    if isinstance(last_element, BaseExpression):
                        raise FiqlFormatException(
                            "%s can not be followed by %s" % (
                                last_element.__class__, Expression))
                    expression = expression.create_nested_expression()
                    nesting_lvl += 1
                elif char == ')':
                    expression = expression.get_parent()
                    last_element = expression
                    nesting_lvl -= 1
                else:
                    if not expression.has_constraint():
                        raise FiqlFormatException(
                            "%s proceeding initial %s" % (
                                Operator, Constraint))
                    if isinstance(last_element, Operator):
                        raise FiqlFormatException(
                            "%s can not be followed by %s" % (
                                Operator, Operator))
                    last_element = Operator(char)
                    expression = expression.add_operator(last_element)
        if selector:
            if isinstance(last_element, BaseExpression):
                raise FiqlFormatException("%s can not be followed by %s" % (
                    last_element.__class__, Constraint))
            last_element = Constraint(selector, comparison, argument)
            expression.add_element(last_element)
    if nesting_lvl != 0:
        raise FiqlFormatException(
            "At least one nested expression was not correctly closed")
    if not expression.has_constraint():
        raise FiqlFormatException(
            "Parsed string '%s' contained no constraint" % fiql_str)
    return expression

def encode_model(obj):
  obj_dict = obj.to_dict()
  for key, val in obj_dict.iteritems():
    if isinstance(val, types.StringType):
      try:
        unicode(val)
