def get_cumulative_data(self):
		sets = map(itemgetter('data'), self.data)
		if not sets:
			return
		sum = sets.pop(0)
		yield sum
		while sets:
			sum = map(add, sets.pop(0))
			yield sum

def reverse_mapping(mapping):
	keys, values = zip(*mapping.items())
	return dict(zip(values, keys))

