def is_glacier(s3_client, bucket, prefix):
    response = s3_client.list_objects_v2(Bucket=bucket,
                                         Prefix=prefix,
                                         MaxKeys=3)  # 3 to not fetch _SUCCESS

    for key in response['Contents']:
        if key.get('StorageClass', 'STANDARD') == 'GLACIER':
            return True
    return False

