        esets[currentset] = []

      # Surfaces
      if env == "surface":
        opt = d["options"]
        currentsurface = opt["name"]
        if opt["type"] == "element":
          surfaces[currentsurface] = []  


    if d["type"] == "data": 
      words = line.strip().split(",")
