def list_characteristics(self):
        paths = self._props.Get(_SERVICE_INTERFACE, 'Characteristics')
        return map(BluezGattCharacteristic,
                   get_provider()._get_objects_by_path(paths))

def start_scan(self, timeout_sec=TIMEOUT_SEC):
        get_provider()._central_manager.scanForPeripheralsWithServices_options_(None, None)
        self._is_scanning = True

def power_off(self, timeout_sec=TIMEOUT_SEC):
        # Turn off bluetooth.
        self._powered_off.clear()
        IOBluetoothPreferenceSetControllerPowerState(0)
        if not self._powered_off.wait(timeout_sec):
            raise RuntimeError('Exceeded timeout waiting for adapter to power off!')

def advertised(self):
        uuids = []
        # Get UUIDs property but wrap it in a try/except to catch if the property
        # doesn't exist as it is optional.
        try:
            uuids = self._props.Get(_INTERFACE, 'UUIDs')
        except dbus.exceptions.DBusException as ex:
            # Ignore error if device has no UUIDs property (i.e. might not be
            # a BLE device).
            if ex.get_dbus_name() != 'org.freedesktop.DBus.Error.InvalidArgs':
                raise ex
        return [uuid.UUID(str(x)) for x in uuids]

def find_descriptor(self, uuid):
        for desc in self.list_descriptors():
            if desc.uuid == uuid:
                return desc
        return None

