def parse_java_version(version_text):
    match = re.search(JAVA_VERSION_REGEX, version_text)
    if not match:
        raise SystemExit(
            'Could not parse Java version from """{}""".'.format(version_text))

    return (int(match.group('major1')), int(match.group('major2')))

