def poisson_random_measure(t, rate, rate_max):
    scale = 1.0 / rate_max
    t = t + exponential(scale)
    while rate_max * uniform() > rate(t):
        t = t + exponential(scale)
    return t

def _current_color(self, which=0):
        if which == 1:
            color = self.colors['edge_loop_color']

        elif which == 2:
            color = self.colors['vertex_color']

        else:
            div = self.coloring_sensitivity * self.num_servers + 1.
            tmp = 1. - min(self.num_system / div, 1)

            if self.edge[0] == self.edge[1]:
                color = [i * tmp for i in self.colors['vertex_fill_color']]
                color[3] = 1.0
            else:
                color = [i * tmp for i in self.colors['edge_color']]
                color[3] = 1 / 2.

        return color

def next_event_description(self):
        if self._departures[0]._time < self._arrivals[0]._time:
            return 2
        elif self._arrivals[0]._time < infty:
            return 1
        else:
            return 0

def simulate(self, n=1, t=None, nA=None, nD=None):
        if t is None and nD is None and nA is None:
            for dummy in range(n):
                self.next_event()
        elif t is not None:
            then = self._current_t + t
            while self._current_t < then and self._time < infty:
                self.next_event()
        elif nD is not None:
            num_departures = self.num_departures + nD
            while self.num_departures < num_departures and self._time < infty:
                self.next_event()
        elif nA is not None:
            num_arrivals = self._oArrivals + nA
            while self._oArrivals < num_arrivals and self._time < infty:
                self.next_event()

def get_queue_data(self, queues=None, edge=None, edge_type=None, return_header=False):
        queues = _get_queues(self.g, queues, edge, edge_type)

        data = np.zeros((0, 6))
        for q in queues:
            dat = self.edge2queue[q].fetch_data()

            if len(dat) > 0:
                data = np.vstack((data, dat))

        if return_header:
            return data, 'arrival,service,departure,num_queued,num_total,q_id'

        return data

def show_type(self, edge_type, **kwargs):
        for v in self.g.nodes():
            e = (v, v)
            if self.g.is_edge(e) and self.g.ep(e, 'edge_type') == edge_type:
                ei = self.g.edge_index[e]
                self.g.set_vp(v, 'vertex_fill_color', self.colors['vertex_highlight'])
                self.g.set_vp(v, 'vertex_color', self.edge2queue[ei].colors['vertex_color'])
            else:
                self.g.set_vp(v, 'vertex_fill_color', self.colors['vertex_inactive'])
                self.g.set_vp(v, 'vertex_color', [0, 0, 0, 0.9])

        for e in self.g.edges():
            if self.g.ep(e, 'edge_type') == edge_type:
                self.g.set_ep(e, 'edge_color', self.colors['edge_active'])
            else:
                self.g.set_ep(e, 'edge_color', self.colors['edge_inactive'])

        self.draw(update_colors=False, **kwargs)
        self._update_all_colors()

