def hashDictOneLevel(myDict):
	keys = [str(x) for x in myDict.keys()]
	keys.sort()

	lst = []
	for key in keys:
		lst.append(str(myDict[key]) + '__~~__')

	return '+_[,'.join(lst).__hash__()

