def custom_prompt(msg, options, default):
    formatted_options = [
        x.upper() if x == default else x.lower() for x in options
    ]
    sure = input("{0} [{1}]: ".format(msg, "/".join(formatted_options)))
    if len(sure) == 0:
        return default
    for option in options:
        if sure.upper() == option.upper():
            return option
    return default

