def setup_axes(rows=1, cols=1, figsize=(8, 6), expand=True, tight_layout=None, **kwargs):

    if expand:
        figsize = (figsize[0]*cols, figsize[1]*rows)

    figargs = {}
    if isinstance(tight_layout, dict):
        figargs["tight_layout"] = tight_layout
    elif tight_layout == "pdf":
        figargs["tight_layout"] = {"rect": (0, 0, 1, 0.95)}

    dpi = kwargs.pop('dpi', None)

    fig, gs = _setup_figure(rows=rows, cols=cols, figsize=figsize, dpi=dpi, **figargs)

    axes = _np.empty(shape=(rows, cols), dtype=object)

    for i in range(rows):
        for j in range(cols):
            axes[i, j] = fig.add_subplot(gs[i, j], **kwargs)

    if axes.shape == (1, 1):
        return fig, axes[0, 0]
    else:
        return fig, axes

def factory_from_graph(cls, data_class, root_args, children):
        graph = cls.factory(data_class, **root_args)
        for child in children:
            cls._depth_create(graph.root, child[0], child[1])

        return graph

def connect_child(self, node):
        if node.graph != self.graph:
            raise AttributeError('cannot connect nodes from different graphs')

        node.parents.add(self)
        self.children.add(node)

def descendents(self):
        visited = set([])
        self._depth_descend(self, visited)
        try:
            visited.remove(self)
        except KeyError:
            # we weren't descendent of ourself, that's ok
            pass

        return list(visited)

