    with open(filename, 'r') as f:
        # Skip the n first lines
        if has_header:
            header = f.readline().strip().split(delimiter)
        else:
            header = None

        for i in range(skip):
            f.readline()

        for line in csv.DictReader(f, delimiter=delimiter, fieldnames=header):
            if use_types:
